/** Validate connection-scoped triggers against the owning organization. */
export async function assertBehaviorTriggerConnections(
	sql: DbClient,
	organizationId: string,
	triggers: BehaviorTrigger[]
): Promise<void> {
	const eventTriggers = triggers.filter(
		(trigger): trigger is BehaviorEventTrigger => trigger.kind === "event"
	);
	const catalogs = new Map<string, ConnectorBehaviorEventCatalog>();
	for (const trigger of eventTriggers) {
		if (trigger.connection_id) {
			const rows = await sql`
				SELECT connector_key
				FROM connections
				WHERE id = ${trigger.connection_id}
				  AND organization_id = ${organizationId}
				  AND deleted_at IS NULL
				LIMIT 1
			`;
			if (rows.length === 0) {
				throw new ToolUserError(
					`Connection ${trigger.connection_id} was not found in this organization.`
				);
			}
			if (String(rows[0]?.connector_key) !== trigger.connector_key) {
				throw new ToolUserError(
					`Connection ${trigger.connection_id} is not a ${trigger.connector_key} connection.`
				);
			}
		}

		let catalog = catalogs.get(trigger.connector_key);
		if (!catalog) {
			catalog = await getConnectorBehaviorEventCatalog(
				sql,
				organizationId,
				trigger.connector_key
			);
			catalogs.set(trigger.connector_key, catalog);
		}
		if (catalog.events.length === 0) {
			throw new ToolUserError(
				`${catalog.name} does not declare any Behavior events.`
			);
		}
		const eventsByKey = new Map(
			catalog.events.map((event) => [event.key, event])
		);
		for (const eventType of trigger.event_types) {
			const event = eventsByKey.get(eventType);
			if (!event) {
				throw new ToolUserError(
					`${catalog.name} does not support Behavior event '${eventType}'.`
				);
			}
			if (trigger.active_run === "steer" && !event.capabilities?.steering) {
				throw new ToolUserError(
					`${catalog.name} event '${eventType}' does not support steering.`
				);
			}
			if (
				trigger.output === "reply_to_source" &&
				!event.capabilities?.replyToSource
			) {
				throw new ToolUserError(
					`${catalog.name} event '${eventType}' does not support replying to the source.`
				);
			}
		}
	}
}
", "/**
 * Organization Access Utilities
 *
 * Provides helpers for organization-scoped database queries with
 * public/private organization support.
 *
 * Access Rules:
 * - Public orgs: Anyone can READ, only members can WRITE
 * - Private orgs: Members only for READ and WRITE
 */

import { type DbClient, getDb } from '../db/client';
import type { ToolContext } from '../tools/registry';
import { ToolUserError } from './errors';

/**
 * Get the user's role in a workspace (organization).
 * Returns null if the user is not a member.
 */
export async function getWorkspaceRole(
  sql: DbClient,
  orgId: string,
  userId: string
): Promise<string | null> {
  const result = await sql`
    SELECT role FROM "member"
    WHERE "organizationId" = ${orgId} AND "userId" = ${userId}
    LIMIT 1
  `;
  return result.length > 0 ? (result[0].role as string) : null;
}

/**
 * Check if user can read an entity
 * Allowed if entity belongs to the user's organization and user is a member.
 */
async function canReadEntity(sql: DbClient, entityId: number, ctx: ToolContext): Promise<boolean> {
  const entityResult = await getDb()`
    SELECT e.organization_id
    FROM entities e
    WHERE e.id = ${entityId}
    LIMIT 1
  `;
  if (entityResult.length === 0) return false;

  const entityOrgId = String(entityResult[0].organization_id);
  if (entityOrgId !== ctx.organizationId) return false;
  if (!ctx.userId) return true;

  const orgRole = await getWorkspaceRole(sql, entityOrgId, ctx.userId);
  return orgRole !== null;
}

/**
 * Check if user can write to an entity (must own it)
 * Only allowed if entity is in user's own organization
 */
async function canWriteEntity(sql: DbClient, entityId: number, ctx: ToolContext): Promise<boolean> {
  const entityRows = await getDb()`
    SELECT organization_id
    FROM entities
    WHERE id = ${entityId}
    LIMIT 1
  `;
  if (entityRows.length === 0) return false;

  const entityOrgId = String(entityRows[0].organization_id);
  if (entityOrgId !== ctx.organizationId) return false;

  // System/internal calls (e.g. reaction scripts) — org match is sufficient
  if (!ctx.userId && ctx.isAuthenticated) return true;
  if (!ctx.userId) return false;

  const membership = await sql`
    SELECT 1
    FROM "member"
    WHERE "organizationId" = ${ctx.organizationId}
      AND "userId" = ${ctx.userId}
      AND role IN ('owner', 'admin')
    LIMIT 1
  `;
  return membership.length > 0;
}

/**
 * Require read access or throw
 */
export async function requireReadAccess(
  sql: DbClient,
  entityId: number,
  ctx: ToolContext
): Promise<void> {
  const canRead = await canReadEntity(sql, entityId, ctx);
  if (!canRead) {
    throw new ToolUserError(`Access denied: entity ${entityId} is not accessible to your organization`, 403);
  }
}

/**
 * Require write access or throw
 */
export async function requireWriteAccess(
  sql: DbClient,
  entityId: number,
  ctx: ToolContext
): Promise<void> {
  const canWrite = await canWriteEntity(sql, entityId, ctx);
  if (!canWrite) {
    throw new ToolUserError(`Access denied: entity ${entityId} does not belong to your organization`, 403);
  }
}

/**
 * Check if the caller may write at the organization level (no entity scope).
 * Used by org-scoped resources like watchers that have their own organization_id.
 */
async function canWriteOrg(sql: DbClient, ctx: ToolContext): Promise<boolean> {
  if (!ctx.organizationId) return false;

  // System/internal calls (e.g. reaction scripts) — authenticated context is sufficient
  if (!ctx.userId && ctx.isAuthenticated) return true;
  if (!ctx.userId) return false;

  const membership = await sql`
    SELECT 1
    FROM "member"
    WHERE "organizationId" = ${ctx.organizationId}
      AND "userId" = ${ctx.userId}
      AND role IN ('owner', 'admin')
    LIMIT 1
  `;
  return membership.length > 0;
}

/**
 * Check if the caller may read at the organization level (no entity scope).
 * Mirrors entity read behavior: once the request is scoped to the organization,
 * anonymous/system contexts are allowed and authenticated users must be members.
 */
async function canReadOrg(sql: DbClient, ctx: ToolContext): Promise<boolean> {
  if (!ctx.organizationId) return false;
  if (!ctx.userId) return true;

  const orgRole = await getWorkspaceRole(sql, ctx.organizationId, ctx.userId);
  return orgRole !== null;
}

/**
 * Require organization-level read access or throw.
 */
export async function requireOrgReadAccess(sql: DbClient, ctx: ToolContext): Promise<void> {
  const ok = await canReadOrg(sql, ctx);
  if (!ok) {
    throw new Error('Access denied: organization-level read access is required');
  }
}

/**
 * Require organization-level write access or throw.
 */
export async function requireOrgWriteAccess(sql: DbClient, ctx: ToolContext): Promise<void> {
  const ok = await canWriteOrg(sql, ctx);
  if (!ok) {
    throw new Error('Access denied: organization-level write access is required');
  }
}
