		ctx,
	)) as { event_id: number | null };
	expect(sent.event_id).toBeGreaterThan(0);

	const sql = getTestDb();
	const [row] = await sql`
		SELECT origin_id, metadata
		FROM events
		WHERE id = ${Number(sent.event_id)}
	`;
