 * default; pass `throwOnFailure` for the agent chat stream, where opening an
 * unauthenticated stream that 403s is worse than surfacing a clear error.
 */
export async function withSseTicket(
  sseUrl: string,
  opts?: { throwOnFailure?: boolean }
): Promise<string> {
  if (!getEmbeddedSessionToken()) return sseUrl;
