import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import {
	createMemoryHistory,
	createRootRoute,
	createRoute,
	createRouter,
	Outlet,
	RouterProvider,
} from "@tanstack/react-router";
import { render, screen, waitFor } from "@testing-library/react";
import type { ReactNode } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";
import { TooltipProvider } from "@/components/ui/tooltip";
import type { ContentItem } from "@/lib/api";
import { EventCard } from "./event-card";

/**
 * An agent's ask is the first interaction that arrives with NO input — the
 * human's answer is the input, and it does not exist yet. That fell through
 * `content.interaction_input || … || {}` to a fresh `{}` on every render, which
 * an effect used as its dependency to re-seed form state. One ask on the feed
 * therefore killed the whole Activity route with "Maximum update depth
 * exceeded" — a runtime-only failure that typecheck and the server suite both
 * stayed green through.
 */

vi.mock("@/components/peek/notification-peek-context", () => ({
	useNotificationPeek: () => ({ item: null, open: vi.fn(), close: vi.fn() }),
}));

vi.mock("@/hooks/use-org-context", () => ({
	useOrgContext: () => ({ currentOwner: "acme" }),
}));

function TestProvider({ children }: { children: ReactNode }) {
	const queryClient = new QueryClient({
		defaultOptions: { queries: { retry: false }, mutations: { retry: false } },
	});
	const rootRoute = createRootRoute({ component: () => <Outlet /> });
	const indexRoute = createRoute({
		getParentRoute: () => rootRoute,
		path: "/",
		component: () => <>{children}</>,
	});
	const router = createRouter({
		routeTree: rootRoute.addChildren([indexRoute]),
		history: createMemoryHistory({ initialEntries: ["/"] }),
	});
	return (
		<QueryClientProvider client={queryClient}>
			<TooltipProvider>
				{/* biome-ignore lint/suspicious/noExplicitAny: test-local router instance */}
				<RouterProvider router={router as any} />
			</TooltipProvider>
		</QueryClientProvider>
	);
}

const ASK = {
	id: 900,
	run_id: 697,
	title: "Acme renewal — how do we play it?",
	text_content: "Contract ends in 11 days.",
	semantic_type: "operation",
	origin_type: "operation",
	interaction_type: "approval",
	interaction_status: "pending",
	// The whole point: an unanswered ask has no input.
	interaction_input: null,
	interaction_input_schema: {
		type: "object",
		properties: {
			play: { title: "The play", enum: ["Discount", "Exec call", "Churn"] },
			discount_pct: { title: "Discount %", type: "number" },
			notify_csm: { title: "Notify CSM", type: "boolean" },
			notes: { title: "Notes", type: "string" },
		},
		required: ["play"],
	},
	metadata: { status: "pending_approval", action_key: "agent_ask" },
} as unknown as ContentItem;

describe("event card renders an unanswered ask", () => {
	afterEach(() => {
		vi.restoreAllMocks();
	});

	it("does not re-render forever when the interaction has no input", async () => {
		// React surfaces the runaway loop as a thrown error during render, so a
		// successful mount IS the assertion. Revert `actionInput` to an inline `{}`
		// fallback and this throws "Maximum update depth exceeded".
		const errors: unknown[] = [];
		vi.spyOn(console, "error").mockImplementation((...args) =>
			errors.push(args[0]),
		);

		const { container } = render(<EventCard content={ASK} />, {
			wrapper: TestProvider,
		});
		await waitFor(() =>
			expect(container.textContent ?? "").not.toEqual(""),
		);

		expect(
			errors.filter((e) => String(e).includes("Maximum update depth")),
		).toHaveLength(0);
	});

	it("renders one control per schema property, labelled from `title`", async () => {
		render(<EventCard content={ASK} />, { wrapper: TestProvider });
		for (const label of ["The play", "Discount %", "Notify CSM", "Notes"]) {
			await waitFor(() => expect(screen.getByText(label)).toBeTruthy());
		}
	});
});

