input.new_string:
/**
 * Who raised this approval, linked to them where there is somewhere to go.
 *
 * A generic approval card used to print `runs`' raw client identity — `pat_1`
 * tells a reviewer nothing. It matters most for an agent's ask: "Should I
 * delete the staging data?" reads very differently from a scheduled Behavior
 * than from an editor plugin someone installed an hour ago, and the reviewer
 * decides on exactly that. Entity-change cards already resolved and linked
 * their proposer; this brings every other family onto the same treatment,
 * reusing `proposerLabelFor` so the two can't drift.
 *
 * An MCP client renders as text: `proposerLabelFor` folds it into the label as
 * "<agent> via <client>", and there is no client route to link to.
 */
function RequestedByLink({
	initiator,
	fallback,
}: {
	initiator: RunInitiator | undefined;
	fallback: string;
}) {
	const { org } = useCurrentOrg();
	const ownerSlug = org?.slug;
	const label =
		initiator && initiator.kind !== "user"
			? proposerLabelFor(initiator, undefined, initiator.watcher_id)
			: fallback;
	const strong = "font-medium text-foreground";
	const linked = `${strong} underline-offset-4 hover:underline`;

	if (ownerSlug && initiator?.kind === "behavior" && initiator.watcher_id) {
		return (
			<Link
				to="/$owner/behaviors/$behaviorId"
				params={{ owner: ownerSlug, behaviorId: String(initiator.watcher_id) }}
				search={{ view: "definition", run_id: undefined }}
				className={linked}
			>
				{label}
			</Link>
		);
	}
	if (ownerSlug && initiator?.kind === "agent_session" && initiator.agent_id) {
		return (
			<Link
				to="/$owner/agents/$agentId"
				params={{ owner: ownerSlug, agentId: String(initiator.agent_id) }}
				className={linked}
			>
				{label}
			</Link>
		);
	}
	return <span className={strong}>{label}</span>;
}

type MergeEvidence = { kind: string; identifier: string };

