 * A recognized MCP client (ChatGPT, Claude, Cursor, Gemini) gets its brand mark
 * and links to its connected-app page — the same `ClientAppIcon` and
 * `/connectors/app/mcp-client?client=` pair the agents list already uses, so a
 * client is the same thing everywhere it appears.
 */
function RequestedByLink({
	initiator,
	clientName,
	fallback,
}: {
	initiator: RunInitiator | undefined;
	/** Free-form client title the MCP session reported, for the brand mark. */
	clientName: string | undefined;
	fallback: string;
}) {
	const { org } = useCurrentOrg();
	const ownerSlug = org?.slug;
	const label =
		initiator && initiator.kind !== "user"
			? proposerLabelFor(
					initiator,
					undefined,
					initiator.watcher_id === undefined
						? undefined
						: String(initiator.watcher_id),
				)
			: fallback;
	const strong = "font-medium text-foreground";
	const linked = `${strong} underline-offset-4 hover:underline`;

	if (ownerSlug && initiator?.kind === "behavior" && initiator.watcher_id) {
		return (
			<Link
				to="/$owner/behaviors/$behaviorId"
				params={{ owner: ownerSlug, behaviorId: String(initiator.watcher_id) }}
				search={{ view: "definition", run_id: undefined }}
				className={linked}
			>
				{label}
			</Link>
		);
	}
	if (ownerSlug && initiator?.kind === "agent_session" && initiator.agent_id) {
		return (
			<Link
				to="/$owner/agents/$agentId"
				params={{ owner: ownerSlug, agentId: String(initiator.agent_id) }}
				className={linked}
			>
				{label}
			</Link>
		);
	}
	// No agent and no Behavior: the MCP client IS the asker. It has a real page,
	// so link it rather than printing its id as dead text.
	const client = initiator?.client_id ?? clientName;
	if (ownerSlug && client) {
		return (
			<Link
				to="/$owner/connectors/app/$appId"
				params={{ owner: ownerSlug, appId: "mcp-client" }}
				search={{ client }}
				className={`${linked} inline-flex items-center gap-1 align-middle`}
			>
				<ClientAppIcon name={clientName ?? client} />
				{label}
			</Link>
		);
	}
	return <span className={strong}>{label}</span>;
}

