  return `${PARENT_MARKER}
**${headline}** for Lobu head \`${lobuHead}\`.

- Owletto range: \`${proof.lobu_base_owletto_sha}\` → \`${proof.owletto_sha}\`
- Proof and approval thread: ${proofUrl}
${approvalLine}`;
}

