import { describe, expect, it } from "bun:test";
import {
  buildProofBody,
  findProofComment,
  isHttpsArtifact,
  parseProof,
  proofMatches,
  selectOwlettoPullRequest,
  type UiReviewComment,
  type UiReviewProof,
} from "../lib/ui-review-proof";
import { githubRepoFromRemote } from "../ui-review";

const BASE_SHA = "1".repeat(40);
--- usage ---
proofMatches               1
isHttpsArtifact            4
parseProof                 3
selectOwlettoPullRequest   3
UiReviewComment            2

3:  let comments = ghApiPages<ApiComment>(
4:    `repos/${owlettoRepo}/issues/${owlettoPr.number}/comments`
6:  let proofComment = findProofComment(comments, lobuRepo, parentPr.number);
52:    comments = ghApiPages<ApiComment>(
53:      `repos/${owlettoRepo}/issues/${owlettoPr.number}/comments`
=== Makefile ===
	@echo "  make review [BASE=<branch>]                - Run the cross-harness LLM reviewer against the local diff (deterministic suites run in CI); posts pi-review status and PR comment"
	@echo "  make review-fix [BASE=<branch>]            - Pre-review fixer: reviewer CLI with write access fixes review-grade findings in the tree; posts nothing"
	@echo "  make ui-review [ARTIFACT=<https-url>]       - Gate an Owletto pointer on exact-SHA visual proof and human approval; OPEN=1 opens its PR"
	@echo "  make owletto-mac [INSTALL=1] [OPEN=1]      - Build Owletto.app with the Developer ID identity (TCC grants match the notarized release); INSTALL=1 replaces /Applications/Owletto.app, OPEN=1 launches it"
	@echo "  make owletto-mac-e2e [SKIP_BUILD=1]        - Build/install the signed Owletto.app then probe prod computer_use (permissions + list_windows) via the paired device connection"
# Visual counterpart to `make review`: non-Owletto PRs pass as not applicable.
# Pointer PRs post/update proof on the exact merged Owletto PR, attach a
# `ui-review` status to this Lobu head, and stay pending until an admin posts
# the SHA-bound approval command shown in that proof. ARTIFACT and OPEN are
# read directly by scripts/ui-review.ts, avoiding shell interpolation of URLs.
ui-review:
	@bun scripts/ui-review.ts

let comments = ghApiPages<ApiComment>(
  `repos/${owlettoRepo}/issues/${owlettoPr.number}/comments`
);
let proofComment = findProofComment(comments, lobuRepo, parentPr.number);
let currentProof = proofComment ? parseProof(proofComment.body) : null;
const exactProof =
  currentProof &&
  proofMatches(
    currentProof,
    lobuRepo,
    basePointer,
    headPointer,
    parentPr.number,
    owlettoPr.number
  );

if (
  !exactProof ||
  (options.artifactUrl && currentProof?.artifact_url !== options.artifactUrl)
) {
  if (!options.artifactUrl) {
    postStatus(
      lobuRepo,
      localHead,
      "error",
      "UI proof missing; rerun make ui-review with ARTIFACT=...",
      owlettoPr.html_url
    );
    if (options.open) openPullRequest(owlettoPr.html_url);
    throw new Error(
      `No current proof on ${owlettoPr.html_url}. Rerun with ARTIFACT=<hosted HTTPS comparison>.`
    );
  }

  currentProof = {
    version: 1,
    lobu_repo: lobuRepo,
    lobu_pr: parentPr.number,
    lobu_base_owletto_sha: basePointer,
    owletto_sha: headPointer,
    owletto_pr: owlettoPr.number,
    artifact_url: options.artifactUrl,
  };
  proofComment = writeComment(
    owlettoRepo,
    owlettoPr.number,
    proofComment,
    buildProofBody(currentProof)
  );
  comments = ghApiPages<ApiComment>(
    `repos/${owlettoRepo}/issues/${owlettoPr.number}/comments`
  );
}

if (!currentProof || !proofComment) {
  throw new Error("UI proof publication did not return a usable comment");
}

